fn numpy_flip(m: Vec<f32>) -> Vec<f32> {
    let n = m.len();
    let mut result = Vec::with_capacity(n); // Create a new vector with the same capacity as m

    for i in (0..n).rev() { // Iterate over indices in reverse order
        result.push(m[i]); // Push elements from m to result in reverse order
    }

    result // Return the reversed vector
}